from pathlib import Path


def _db(ws):
    return sqlite3.connect(Path(ws).parent / "system" / "leaseaccelerator_lease_accounting" / "state.db")


def _norm(value):
    return " ".join(str(value or "").casefold().replace("-", " ").split())


def check_payment_stream_exception_post_state(ws):
    con = _db(ws)
    try:
        try:
            rows = con.execute(
                "SELECT lease_id, payment_stream_id, exception_type, description, raised_by, idempotency_key, status "
                "FROM payment_stream_exceptions WHERE idempotency_key = ?",
                ("T005-SEP2024-LA-2024-017-COMPLETENESS",),
            ).fetchall()
        except sqlite3.OperationalError:
            return {"score": 0, "detail": "The payment-stream exception record was not created."}
        if len(rows) != 1:
            return {"score": 0, "detail": f"Expected one idempotent exception, found {len(rows)}."}
        lease_id, stream_id, exception_type, description, raised_by, key, status = rows[0]
        text = _norm(description)
        required = ["september 2024", "excluded", "renewal", "latest", "source", "stream"]
        ok = (
            lease_id == "LA-2024-017" and stream_id == "PS-2024-017-V2" and
            exception_type == "COMPLETENESS" and raised_by == "Sarah Chen" and
            key == "T005-SEP2024-LA-2024-017-COMPLETENESS" and status == "OPEN" and
            all(term in text for term in required)
        )
        return {"score": int(ok), "detail": f"exception={rows[0]}"}
    finally:
        con.close()


def check_preserve_source_accounting_records(ws):
    con = _db(ws)
    try:
        streams = con.execute(
            "SELECT payment_stream_id, lease_id, payment_start_date, payment_end_date, payment_frequency, "
            "fixed_payment_cents, annualized_fixed_payment_cents, currency_code, component_combination_flag, "
            "source_version, superseded_flag, duplicate_of_stream_id, source_file_name "
            "FROM lease_payment_streams WHERE payment_stream_id IN (?, ?) ORDER BY payment_stream_id",
            ("PS-2024-017-V1", "PS-2024-017-V2"),
        ).fetchall()
        expected = [
            ("PS-2024-017-V1", "LA-2024-017", "2024-01-07", "2034-01-06", "MONTHLY", 7150000, 85800000, "USD", 1, 1, 1, None, "US_RENT_ROLL_2024-08-30.csv"),
            ("PS-2024-017-V2", "LA-2024-017", "2024-01-07", "2034-01-06", "MONTHLY", 7304527, 87654321, "USD", 1, 2, 0, "PS-2024-017-V1", "US_RENT_ROLL_2024-09-18.csv"),
        ]
        if streams != expected:
            return {"score": 0, "detail": "A source payment stream was edited, superseded, or deleted."}
        count = con.execute(
            "SELECT COUNT(*) FROM measurement_components WHERE lease_id = ?",
            ("LA-2024-017",),
        ).fetchone()[0]
        if count != 0:
            return {"score": 0, "detail": f"Measurement component count changed from 0 to {count}."}
        return {"score": 1, "detail": "Source payment streams and measurement components remain unchanged."}
    finally:
        con.close()
